{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_none_counts_as_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}, {"flagged": False}]) == 1 / 3
    assert monitor_flag_rate([{"flagged": None}]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 3), (2, 5), (3, 6), (10, 6)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected
    assert flags_in_window([], days) == 0


def test_parse_values_whitespace_and_skipped_lines():
    lines = ["\n", "  # comment,not,a,record", " a , 2 , 1 ", "b, -3, 0", " c, 4,   "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 2, "flagged": True},
        {"id": "b", "day": -3, "flagged": False},
        {"id": "c", "day": 4, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,nope,1", "a,1,yes"])
def test_parse_errors_include_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_transcript_log(["  ", " # comment", bad_line])


def test_dedupe_keeps_last_duplicate_id_and_sorts_by_day_then_id():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": True},
        {"id": "a", "day": 3, "flagged": False},
        {"id": "c", "day": 2, "flagged": None},
        {"id": "b", "day": 2, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[4], events[3], events[2]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_with_gaps_and_outside_events():
    events = [
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": None},
        {"day": 3, "flagged": False},
        {"day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_monitor_summary_uses_calendar_days_and_nonempty_groups():
    groups = {
        "one": [{"day": 1, "flagged": True}],
        "other": [{"day": 4, "flagged": False}] * 5,
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.167, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 4)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_ties_and_empty_groups():
    groups = {
        "z": [{"flagged": True}],
        "empty": [],
        "b": [{"flagged": True}, {"flagged": False}],
        "a": [{"flagged": True}, {"flagged": None}],
    }
    assert top_flagged_groups(groups, 10) == ["z", "a", "b"]
    assert top_flagged_groups(groups, 2) == ["z", "a"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_orders_keys_and_handles_empty():
    result = flag_rate_by_group({"z": [], "b": [{"flagged": False}], "a": [{"flagged": True}]})
    assert list(result.items()) == [("a", 1.0), ("b", 0.0), ("z", None)]


def test_longest_flag_streak_resets_on_nonpositive_counts():
    assert longest_flag_streak([1, 2, 0, 3, -1, 1, 2, 3]) == 3
    assert longest_flag_streak([-1, 0, -2]) == 0
    assert longest_flag_streak([]) == 0
